<template><section aria-label="单位换算"><div class="tool-actions"><label>换算类型<select v-model="group" aria-label="换算类型" @change="resetUnits"><option v-for="(item,key) in groups" :key="key" :value="key">{{ item.label }}</option></select></label></div><div class="unit-inputs"><label class="tool-label">数值<input v-model="value" inputmode="decimal" aria-label="换算数值" /></label><label class="tool-label">从<select v-model="from" aria-label="原单位"><option v-for="unit in units" :key="unit" :value="unit">{{ unit }}</option></select></label><button type="button" @click="swap">交换单位</button><label class="tool-label">到<select v-model="to" aria-label="目标单位"><option v-for="unit in units" :key="unit" :value="unit">{{ unit }}</option></select></label></div><p v-if="result.error" role="status" class="tool-error">{{ result.error }}</p><output v-else class="unit-result" aria-live="polite">{{ formatted }} {{ to }}</output><p class="tool-note">B 是字节，bit 是位，1 B = 8 bit。kB / MB 使用 1000 进制，KiB / MiB 使用 1024 进制；网速与实际下载速度还受网络开销影响。</p><button type="button" :disabled="!!result.error" @click="copy">复制换算结果</button><p role="status">{{ message }}</p></section></template>
<script>
import { unitGroups, convertUnits, displayNumber } from '../../utils/utility-tools.mjs';
export default { name: 'UnitTool', data: () => ({ groups: unitGroups, group: 'storage', value: '1024', from: 'B', to: 'KiB', message: '' }), computed: { units() { return Object.keys(this.groups[this.group].units); }, result() { return convertUnits(this.value, this.group, this.from, this.to); }, formatted() { return this.result.error ? '' : displayNumber(this.result.value); } }, methods: { resetUnits() { this.from = this.units[0]; this.to = this.units[1]; this.message = ''; }, swap() { if (!this.result.error) this.value = String(this.result.value); [this.from, this.to] = [this.to, this.from]; }, async copy() { try { await navigator.clipboard.writeText(this.formatted + ' ' + this.to); this.message = '已复制换算结果'; } catch { this.message = '复制未完成，请选中结果手动复制'; } } } };
</script>
